def count_good_substrings(s):
    count = 0
    for i in range(len(s) - 2):
        window = s[i:i + 3]
        if len(set(window)) == 3:                                       # all three characters are distinct
            count += 1
    return count


if __name__ == "__main__":
    print(count_good_substrings("xyzzaz"))

