import java.util.*;

public class Main {
    int countGoodSubstrings(String s) {
        Map<Character, Integer> freq = new HashMap<>();
        int count = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            freq.merge(c, 1, Integer::sum);
            if (i >= 3) {
                char leaving = s.charAt(i - 3);
                freq.merge(leaving, -1, Integer::sum);
                if (freq.get(leaving) == 0) freq.remove(leaving);                  // stop tracking a character once it's no longer in the window
            }
            if (i >= 2 && freq.size() == 3) {                                       // window is full size AND all three characters are distinct
                count++;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.countGoodSubstrings("xyzzaz"));
    }
}

