#include <bits/stdc++.h>
using namespace std;

int countGoodSubstrings(string s) {
    unordered_map<char,int> freq;
    int count = 0;
    for (int i = 0; i < (int)s.size(); i++) {
        freq[s[i]]++;
        if (i >= 3) {
            char leaving = s[i - 3];
            freq[leaving]--;
            if (freq[leaving] == 0) freq.erase(leaving);                        // stop tracking a character once it's no longer in the window
        }
        if (i >= 2 && (int)freq.size() == 3) {                                  // window is full size AND all three characters are distinct
            count++;
        }
    }
    return count;
}

int main() {
    cout << countGoodSubstrings("xyzzaz") << endl;
    return 0;
}
